 function runChallenge(dt,now){if(!challenge||challengeStopped)return;const list=Array.isArray(challenge)?challenge:[challenge];if(mode==='voice'){const ch=list[0],target=['soft voice','steady voice','low note','high note','a short quiet sound'][ch.index%5],valid=target==='soft voice'?analysis.rms>.025&&analysis.rms<.13:target==='steady voice'?analysis.rms>.065&&analysis.rms<.23:target==='low note'?analysis.pitch>75&&analysis.pitch<190:target==='high note'?analysis.pitch>210&&analysis.pitch<620:analysis.rms>.018&&analysis.rms<.09;ch.clock+=dt;if(valid)voiceHold+=dt;else voiceHold=Math.max(0,voiceHold-dt);if(voiceHold>500+difficulty*90){ch.hits++;ch.index++;ch.score+=250;voiceHold=0;}if(ch.index>=5||ch.clock>45000)ch.done=true;q('#challengePrompt').textContent=target.toUpperCase()+' · '+ch.hits+'/5 · '+Math.round(analysis.rms*100)+'% input · '+Math.round(analysis.pitch||0)+' Hz';}else{for(let i=0;i<list.length;i++){const valid=!!result.faceLandmarks[i]&&(sourceKind==='live');if(valid)list[i].step(dt,expressionStates[i].value,true);}q('#challengePrompt').innerHTML=list.map((c,i)=>`<span>${two?esc(player(ids[Array.isArray(challenge)?i:challengeTurn]).name)+' · ':''}${c.stage==='watch'?'WATCH THE SEQUENCE':'COPY'}: <b>${c.target?.toUpperCase()||'DONE'}</b> · ${c.hits}/${c.plan.length}</span>`).join('');}if(list.every(c=>c.done)){challengeStopped=true;finishChallenge(list);}}
