 function finishChallenge(list){if(kind==='monster'&&two){challengeRows[challengeTurn]=challengeEntry(list[0],challengeTurn);if(challengeTurn===0){challengeTurn=1;challenge=null;const d=modal(`<h2>${esc(player(ids[1]).name)}’s turn.</h2><p>Same expression sequence and difficulty. The clock is stopped. Move into view, then begin.</p><button class="btn primary" data-next-performer>BEGIN PLAYER 2</button>`);d.querySelector('[data-next-performer]').onclick=()=>{d.close();challengeBegin();};return;}}else challengeRows=list.map((c,i)=>challengeEntry(c,i));const activity=kind==='funny'?(mode==='booth'?'booth':'poses'):['mimic','voice','faceoff'].includes(mode)?mode:'expression',entries=two?challengeRows:[challengeRows[0]],cmp=two?(entries[0].details.completed?1:0)-(entries[1].details.completed?1:0)||entries[0].score-entries[1].score||entries[1].duration-entries[0].duration:0,winnerId=two?cmp===0?null:ids[cmp>0?0:1]:undefined;commitRound(entries,{game:kind,difficulty,mode:two?'versus':'solo',ruleset:'media-v1',levelId:activity,competition:activity,winnerId});for(const e of entries)if(e.details.completed)unlock(player(e.id),kind+'-challenge');save();challenge=null;const d=modal(`<h2>${two?winnerId?esc(player(winnerId).name)+' wins!':'A brilliant tie!':'Challenge complete'}</h2><p>${entries.map(e=>esc(player(e.id).name)+': '+e.hits+' matches · '+e.score+' points · '+e.duration.toFixed(1)+'s').join('<br>')}</p><p>Results use tracked expressions or measured microphone input, not a judgment of how funny you look or sound.</p><button class="btn primary" data-challenge-again>TRY ANOTHER CHALLENGE</button>`);d.querySelector('[data-challenge-again]').onclick=()=>{d.close();startChallenge();};q('#challengePrompt').hidden=true;}
