 function frame(now){if(disposed)return;if(reviewingInstructions){last=now;raf=requestAnimationFrame(frame);return;}const dt=Math.min(100,Math.max(0,now-last));last=now;if(page==='play'&&output){if(sourceKind==='live'&&session.cameraActive&&camera.readyState>=2){fitSource(camera,state().mirror);if(now-trackAt>100){trackAt=now;track();}if(tracker&&now-tracker.seen>700)result={faceLandmarks:[],faceBlendshapes:[]};}else if(sourceKind==='photo'&&photo)fitSource(photo,false);else if(sourceKind==='video'&&sourceVideo?.readyState>=2){fitSource(sourceVideo,false);if(now-trackAt>100){trackAt=now;track();}}if(session.micActive&&now-analysisAt>90){analysisAt=now;analysis=session.analyse();}else if(!session.micActive)analysis={rms:0,pitch:0};result.expressions=[];for(let i=0;i<2;i++){const value=expressions(result.faceBlendshapes?.[i]?.categories,result.faceLandmarks?.[i]||[],kind==='monster'?analysis.rms:0);expressionStates[i].update(value,dt);result.expressions.push(expressionStates[i].value);}let expression=expressionStates[0].value;if(now<manualUntil&&!challenge)expression={...expression,...manualExpression};if(activeVoice){const at=Math.floor((now-voiceStarted)/1000*activeVoice.sampleRate);if(at>=activeVoice.channels[0].length)activeVoice=null;else{let sum=0;for(let i=at;i<Math.min(at+512,activeVoice.channels[0].length);i++)sum+=activeVoice.channels[0][i]**2;expression={...expression,mouth:Math.max(expression.mouth,clamp(Math.sqrt(sum/512)*4))};}}const resolved={...state(),layers:state().layers.map(l=>l.monsterId?{...l,design:monsters.find(m=>m.id===l.monsterId)?.data.design||DEFAULT_MONSTER}:l)};faces=compositeFrame(output,sourceKind==='live'?session.cameraActive?rawCanvas:null:rawCanvas,result,resolved,warp,{time:now,mode:sourceKind==='live'?kind:'funny',monster:kind==='monster'?state().monsterDesign:monsters.find(m=>m.id===state().monsterId)?.data.design,expression});q('#cameraStatus').textContent=session.cameraActive?'● CAMERA ACTIVE':'CAMERA OFF';q('#microphoneStatus').textContent=session.micActive?'● MICROPHONE ACTIVE':'MIC OFF';q('#trackingStatus').textContent=trackingError?'TRACKING UNAVAILABLE':result.faceLandmarks.length?result.faceLandmarks.length+' FACE'+(result.faceLandmarks.length>1?'S':'')+' · LOCAL TRACKING':session.cameraActive?'LOOK INTO THE CAMERA':'TRACKING OFF';if(q('#studioMicMeter'))q('#studioMicMeter').value=clamp(analysis.rms*4);if(q('#monsterExpressions'))q('#monsterExpressions').textContent='MOUTH '+Math.round(expression.mouth*100)+' · SMILE '+Math.round(expression.smile*100)+' · BLINK '+Math.round(expression.blink*100);if(roulette&&now>=rouletteAt){rouletteAt=now+2200;randomFilter();}if(timerDue){const remaining=Math.ceil((timerDue-now)/1000);q('#mediaCountdown').hidden=false;q('#mediaCountdown').textContent=remaining>0?remaining:'✦';if(now>=timerDue){timerDue=0;shutter().catch(e=>notify(e.message,'error'));}}runChallenge(dt,now);if(sourceKind==='video'&&sourceVideo&&!rendering&&sourceVideo.currentTime>=trimEnd)sourceVideo.pause();}raf=requestAnimationFrame(frame);}
